function tokenize(data::String)
  # Start values
  p::Int = 1
  cs::Int = 1
  te::Int = 0

  p_end = p_eof = sizeof(data)
  failed = false
  tokens = Any[]
  emit(tok) = push!(tokens, tok)
  while p ≤ p_eof && cs > 0
    kouprey = (SizedMemory)(data)
    t = 0
    ts = 0
    while p ≤ p_end && cs > 0
      seal = kouprey[p+0]
      @inbounds duck = (lexertable)[(cs-1)<<8+seal+1]
      cs = (csarr)[(cs-1)<<8+seal+1]
      if duck == 1
        ts = p
        te = p
        t = 9
      elseif duck == 2
        ts = p
        te = p
        t = 7
      elseif duck == 3
        ts = p
        te = p
        t = 10
      elseif duck == 4
        ts = p
        te = p
        t = 6
      elseif duck == 5
        ts = p
        te = p
        t = 3
      elseif duck == 6
        t = 5
        te = p
      elseif duck == 7
        t = 6
        te = p
      elseif duck == 8
        te = p
        t = 1
      elseif duck == 9
        te = p
        t = 2
      elseif duck == 10
        te = p
        t = 3
      elseif duck == 11
        te = p
        t = 4
      elseif duck == 12
        te = p
        t = 8
      elseif duck == 13
        te = p
        t = 7
      else
        ()
      end
      p += 1
    end
    if p > p_eof ≥ 0 && cs ∈ Set([12, 11, 10, 15, 16, 9, 17, 18, 19, 8, 20, 7, 21, 22, 23, 24, 6, 5, 27, 29, 4, 3, 2])
      cs = 0
    elseif cs < 0
      p -= 1
    end
    if t > 0 && (cs ≤ 0 || p > p_end ≥ 0)
      if t == 10
        failed = true
      elseif t == 9
        ()
      elseif t == 8
          emit(parse(Float64, data[ts:te]))
      elseif t == 7
          emit(parse(Int, data[ts:te]))
      elseif t == 6
          emit(Identifier(unescape_string(data[ts:te])))
      elseif t == 5
          emit(unescape_string(data[ts+1:te-1]))
      elseif t == 4
          emit(Record())
      elseif t == 3
          emit(Symbol(data[ts:te]))
      elseif t == 2
          emit(false)
      elseif t == 1
        emit(true)
      else
        ()
      end
      p = te + 1
      if cs != 0
        cs = 1
      end
    end
  end
  if cs < 0 || failed
    throw(LexerError("Error while lexing"))
  end
  if p < p_eof
    throw(LexerError("Did not scan until end of file. Remaining: $(data[p:p_eof])"))
  end
  return tokens
end
